import{_ as i,o as a,c as r,a0 as e}from"./chunks/framework.L_oL6aia.js";const p=JSON.parse('{"title":"Karing 客户端使用教程","description":"","frontmatter":{},"headers":[],"relativePath":"guide/karing.md","filePath":"guide/karing.md"}'),s={name:"guide/karing.md"};function l(o,t,n,g,c,d){return a(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="karing-客户端使用教程" tabindex="-1">Karing 客户端使用教程 <a class="header-anchor" href="#karing-客户端使用教程" aria-label="Permalink to &quot;Karing 客户端使用教程&quot;">​</a></h1><p>本教程将引导您完成 <strong>Karing 客户端</strong> 的安装与配置。</p><p>Karing 是一款支持 <strong>Windows、Android、macOS、iOS</strong> 多平台的网络代理工具，各平台界面与操作逻辑基本一致。本教程以 <strong>Windows 端</strong> 为例进行演示。</p><hr><h2 id="一、软件下载" tabindex="-1">一、软件下载 <a class="header-anchor" href="#一、软件下载" aria-label="Permalink to &quot;一、软件下载&quot;">​</a></h2><p>请根据您的设备系统，选择对应的安装包进行下载：</p><table tabindex="0"><thead><tr><th style="text-align:left;">操作系统</th><th style="text-align:left;">适用设备 / 芯片</th><th style="text-align:left;">下载文件名 / 方式</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Windows</strong></td><td style="text-align:left;">64位通用</td><td style="text-align:left;"><code>karing_windows_x64.exe</code></td></tr><tr><td style="text-align:left;"><strong>Android</strong></td><td style="text-align:left;">安卓手机 / 平板</td><td style="text-align:left;"><code>karing_android.apk</code></td></tr><tr><td style="text-align:left;"><strong>macOS</strong></td><td style="text-align:left;">Intel 芯片</td><td style="text-align:left;"><code>karing_macos.dmg</code></td></tr><tr><td style="text-align:left;"><strong>macOS / iOS</strong></td><td style="text-align:left;">Apple Silicon（M系列）/ iPhone / iPad</td><td style="text-align:left;">登录美区 Apple ID，前往 App Store 搜索 <strong>Karing</strong> 下载</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">💡 大陆用户下载提示</p><p>如官方网站访问较慢，可使用备用下载通道：<a href="https://doc.xhyjs.top/" target="_blank" rel="noreferrer">https://doc.xhyjs.top/</a></p></div><hr><h2 id="二、快速使用指南" tabindex="-1">二、快速使用指南 <a class="header-anchor" href="#二、快速使用指南" aria-label="Permalink to &quot;二、快速使用指南&quot;">​</a></h2><h3 id="step-1-基础初始化设置" tabindex="-1">Step 1. 基础初始化设置 <a class="header-anchor" href="#step-1-基础初始化设置" aria-label="Permalink to &quot;Step 1. 基础初始化设置&quot;">​</a></h3><p>下载完成后，双击打开安装包 <code>karing_windows_x64.exe</code>。首次启动 Karing 时会进入新手引导流程，请按照以下步骤完成设置：</p><ol><li><strong>选择地区</strong>：在地区选择界面选择 <strong>中国（China）</strong>，点击 <strong>下一步</strong>。</li><li><strong>开启模式</strong>：根据界面提示选择开启 <strong>新手模式</strong>。</li></ol><details><summary><b>📸 点击展开查看初始化步骤截图（共14张）</b></summary><br><img src="https://doc.mimy.cc/gykaring11.webp" width="600" alt="初始化设置 01"><img src="https://doc.mimy.cc/gykaring22.webp" width="600" alt="初始化设置 02"><img src="https://doc.mimy.cc/gykaring33.webp" width="600" alt="初始化设置 03"><img src="https://doc.mimy.cc/gykaring44.webp" width="600" alt="初始化设置 04"><img src="https://doc.mimy.cc/gykaring55.webp" width="600" alt="初始化设置 05"><img src="https://doc.mimy.cc/gykaring66.webp" width="600" alt="初始化设置 06"><img src="https://doc.mimy.cc/gykaring77.webp" width="600" alt="初始化设置 07"><img src="https://doc.mimy.cc/gykaring88.webp" width="600" alt="初始化设置 08"><img src="https://doc.mimy.cc/gykaring111.webp" width="600" alt="初始化设置 09"><img src="https://doc.mimy.cc/gykaring222.webp" width="600" alt="初始化设置 10"><img src="https://doc.mimy.cc/gykaring333.webp" width="600" alt="初始化设置 11"><img src="https://doc.mimy.cc/gykaring444.webp" width="600" alt="初始化设置 12"><img src="https://doc.mimy.cc/gykaring555.webp" width="600" alt="初始化设置 13"><img src="https://doc.mimy.cc/gykaring666.webp" width="600" alt="初始化设置 14"></details><hr><h3 id="step-2-导入订阅地址" tabindex="-1">Step 2. 导入订阅地址 <a class="header-anchor" href="#step-2-导入订阅地址" aria-label="Permalink to &quot;Step 2. 导入订阅地址&quot;">​</a></h3><p>完成初始化后，需要将订阅链接导入 Karing 以获取节点信息：</p><ol><li>登录 <strong>fangqi 官网</strong>，复制您的专属订阅地址。</li><li>打开 Karing 客户端，进入 <strong>配置管理</strong> 页面，点击 <strong>从剪切板导入</strong>。</li><li>软件会自动识别已复制的链接，在 <strong>备注</strong> 栏输入 <code>fangqi</code>。</li><li>点击右上角的 <strong><code>✓</code> 保存</strong> 按钮。</li></ol><img src="https://img.mimy.cc/fangqi0303.webp" width="600" alt="复制订阅地址"><img src="https://img.mimy.cc/fangqi0404.webp" width="600" alt="配置管理界面"><img src="https://doc.mimy.cc/gykaring999.webp" width="600" alt="从剪切板导入"><img src="https://img.mimy.cc/fangqiK111.webp" width="600" alt="保存订阅配置"><hr><h3 id="step-3-节点选择与延迟测试" tabindex="-1">Step 3. 节点选择与延迟测试 <a class="header-anchor" href="#step-3-节点选择与延迟测试" aria-label="Permalink to &quot;Step 3. 节点选择与延迟测试&quot;">​</a></h3><p>成功导入订阅后，建议在连接前进行延迟测试，选择速度较快且稳定的节点：</p><ol><li>点击左上角 <strong>返回</strong>，回到主界面。</li><li>点击底部的 <strong><code>&gt;</code></strong> 按钮进入节点列表，并展开显示全部节点。</li><li>点击 <strong>闪电图标</strong>，对所有节点进行全局延迟测试。</li><li>测试完成后，点击选择您需要使用的目标节点（单个节点也可点击其右侧的 <strong>三角形/数字</strong> 单独测速）。</li></ol><div class="info custom-block"><p class="custom-block-title">延迟测试说明</p><ul><li><strong>数值越低</strong>：网络延迟越小，连接速度越快。</li><li><strong>⚠️ 警告图标</strong>：表示该节点当前连接异常，可能无法正常上网。</li></ul></div><img src="https://doc.mimy.cc/xhykaring22.webp" width="600" alt="返回主界面"><img src="https://doc.mimy.cc/xhykaring33.webp" width="600" alt="进入节点列表"><img src="https://img.mimy.cc/fangqiK222.webp" width="600" alt="全局延迟测试"><img src="https://doc.mimy.cc/xhykaring66.webp" width="600" alt="选择目标节点"><hr><h3 id="step-4-开启代理服务" tabindex="-1">Step 4. 开启代理服务 <a class="header-anchor" href="#step-4-开启代理服务" aria-label="Permalink to &quot;Step 4. 开启代理服务&quot;">​</a></h3><ol><li>点击左上角 <strong>返回</strong> 回到主界面。</li><li>点击屏幕中央下方的 <strong>电源开关按钮</strong>。</li><li>连接成功后： <ul><li>开关状态由红色 <strong><code>✕</code></strong> 变为绿色 <strong><code>✓</code></strong>。</li><li>下方将显示当前已连接的节点名称。</li></ul></li></ol><img src="https://img.mimy.cc/fangqiK444.webp" width="600" alt="开启代理服务"><hr><h3 id="step-5-日常维护-更新订阅" tabindex="-1">Step 5. 日常维护：更新订阅 <a class="header-anchor" href="#step-5-日常维护-更新订阅" aria-label="Permalink to &quot;Step 5. 日常维护：更新订阅&quot;">​</a></h3><p>当节点连接失败、失效或需要同步套餐剩余流量时，可进行手动更新：</p><ol><li>进入主界面的 <strong>我的配置</strong>。</li><li>找到已添加的配置项，点击右侧的 <strong>云朵图标（更新）</strong>。</li><li>等待同步完成，即可获取最新节点数据。</li></ol><img src="https://img.mimy.cc/fangqiK555.webp" width="600" alt="我的配置"><img src="https://img.mimy.cc/fangqiK666.webp" width="600" alt="更新订阅">',41)])])}const m=i(s,[["render",l]]);export{p as __pageData,m as default};
